import{_ as o,C as s,o as d,c as e,j as i,a as t,E as r,a3 as l}from"./chunks/framework.C6R8kWFE.js";const j=JSON.parse(`{"title":"13-dars (Mentor). UI kit va dizayn tizimi tushunchasi","description":"","frontmatter":{"title":"13-dars (Mentor). UI kit va dizayn tizimi tushunchasi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"week":{"n":5,"link":"/mentor/9-sinf/hafta-05/"},"g":13,"title":"UI kit va dizayn tizimi tushunchasi","lead":"Bitta ilovaning 10 ta ekranida 10 xil ko'k tugma bo'lsa, foydalanuvchi buni darhol «tartibsizlik» deb sezadi. Katta kompaniyalar bu muammoni UI kit va dizayn tizimlari bilan hal qiladi. Bugun ular nima ekanini bilib olasiz va o'zingizning birinchi mini UI kitingizni yaratasiz.","slide":"/slaydlar/9-sinf/hafta-05/dars-1.html","test":"/slaydlar/9-sinf/hafta-05/dars-1-test.html","student_link":"/9-sinf/hafta-05/dars-1","tabs":[{"g":13,"link":"/mentor/9-sinf/hafta-05/dars-1","current":true},{"g":14,"link":"/mentor/9-sinf/hafta-05/dars-2","current":false},{"g":15,"link":"/mentor/9-sinf/hafta-05/dars-3","current":false}],"prev":null,"next":{"g":14,"title":"Mashhur UI kitlar: HIG, Ant Design, Bootstrap, Figma UI Kit, Material UI","link":"/mentor/9-sinf/hafta-05/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf/hafta-05/dars-1.md","filePath":"mentor/9-sinf/hafta-05/dars-1.md"}`),m={name:"mentor/9-sinf/hafta-05/dars-1.md"},h={class:"blk"},g={id:"_1-dars-rejasi",tabindex:"-1"},u={class:"blk"},y={id:"_2-dars-konspekti",tabindex:"-1"},k={class:"blk"},p={id:"_3-amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},b={class:"blk"},z={id:"_4-tezkor-nazorat-savollar-va-javoblar",tabindex:"-1"},f={class:"blk"},v={id:"_5-uyga-vazifa",tabindex:"-1"};function q(c,a,_,x,I,U){const n=s("Icon");return d(),e("div",null,[a[15]||(a[15]=i("p",null,[i("strong",null,"Hafta:"),t(" 5 · "),i("strong",null,"Davomiyligi:"),t(" 80 daqiqa · "),i("strong",null,"Turi:"),t(" ma'ruza + dizayn amaliyoti (Figma) · "),i("strong",null,"I-bob"),t(", 1.5-mavzu, 1-dars")],-1)),a[16]||(a[16]=i("p",null,[i("strong",null,"Manba:"),t(" o'quv qo'llanma, 1.5 «UI kit va dizayn tizimlariga kirish» (UI Kit ta'rifi, asosiy maqsadi, 4 ta afzallik: vaqtni tejash, vizual uyg'unlik, moslashuvchanlik, jamoaviy ishlash; mashhur UI kitlar ro'yxati); uslubiy ko'rsatma, 1.4 «UI kit va dizayn tizimlariga kirish» (UI Kit — vizual «konstruktor», yagona uslub; dizayn tizimi — yagona konseptual tizim; 5 asosiy qism: komponentlar, vizual uslublar/tokenlar, shablonlar, prinsip va qo'llanmalar, hujjatlashtirish). Atom → molekula → organizm ierarxiyasi va Figma'dagi Color/Text styles — qo'llanma mazmunini tushuntirish uchun qo'shimcha (Figma rasmiy funksiyalari asosida).")],-1)),i("div",h,[i("h2",g,[r(n,{name:"file-text"}),a[0]||(a[0]=t(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=l('<p><strong>Maqsad:</strong> o&#39;quvchilar UI Kit va dizayn tizimi (Design System) tushunchalarini, ularning farqi va UI/UX dizayndagi ahamiyatini o&#39;rganadi; 4-haftada tanlangan ranglar, shriftlar va oraliqlardan foydalanib, Figma&#39;da «E-kutubxona» loyihasi uchun birinchi mini UI kit sahifasini (ranglar, tipografiya, tugmalar) yaratadi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>UI Kit ta&#39;rifini aytadi va uni «konstruktor» o&#39;xshatishi bilan tushuntiradi;</li><li>UI Kit&#39;ning 4 ta afzalligini misol bilan izohlaydi;</li><li>Dizayn tizimining 5 ta asosiy qismini sanaydi va UI Kit&#39;dan farqini ko&#39;rsatadi;</li><li>Dizayn tokeni (rang, shrift, bo&#39;shliq qiymati) nima ekanini tushunadi;</li><li>Figma&#39;da Color va Text styles yaratib, ulardan 3 ta tugma holatida foydalanadi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>Rang (60-30-10), shrift ierarxiyasi, 8-point grid. Muammo: «10 ta ekranda 10 xil ko&#39;k tugma — nima bo&#39;ladi?»</td></tr><tr><td>10–35 daq</td><td>Yangi mavzu</td><td>UI Kit, afzalliklari, dizayn tizimi va 5 qismi, tokenlar, atom → molekula → organizm</td></tr><tr><td>35–40 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>40–70 daq</td><td>Amaliy mashg&#39;ulot</td><td>Figma&#39;da «E-kutubxona UI kit» sahifasi: ranglar, tipografiya, tugmalar</td></tr><tr><td>70–76 daq</td><td>Tezkor nazorat</td><td>5 ta savol</td></tr><tr><td>76–80 daq</td><td>Xulosa va uyga vazifa</td><td>Keyingi dars: mashhur UI kitlar (HIG, Ant Design, Bootstrap, Figma, Material UI)</td></tr></tbody></table><hr>',5))]),i("div",u,[i("h2",y,[r(n,{name:"file-text"}),a[3]||(a[3]=t(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=l(`<h3 id="_2-1-muammo-«10-xil-ko-k-tugma»" tabindex="-1">2.1. Muammo: «10 xil ko&#39;k tugma» <a class="header-anchor" href="#_2-1-muammo-«10-xil-ko-k-tugma»" aria-label="Permalink to &quot;2.1. Muammo: «10 xil ko&#39;k tugma»&quot;">​</a></h3><p>Katta loyihada 5 ta dizayner har biri o&#39;z tugmasini chizsa: ranglar biroz farq qiladi (#1E88E5, #2196F3, #1976D2...), burchaklar 4, 8, 12 px, shriftlar har xil. Foydalanuvchi bu ilovani «tartibsiz» deb his qiladi, dasturchi esa har bir tugmani alohida kodlaydi. Yechim — <strong>UI Kit</strong> va <strong>dizayn tizimi</strong>.</p><h3 id="_2-2-ui-kit-nima" tabindex="-1">2.2. UI Kit nima? <a class="header-anchor" href="#_2-2-ui-kit-nima" aria-label="Permalink to &quot;2.2. UI Kit nima?&quot;">​</a></h3><p><strong>UI Kit (User Interface Kit)</strong> — dizaynerlar va dasturchilar uchun mo&#39;ljallangan, <strong>tayyor va qayta ishlatiladigan</strong> foydalanuvchi interfeysi komponentlari to&#39;plami. U tugmalar, ikonalar, formalar, navigatsiya panellari, modal oynalar va boshqa elementlarni tayyor shaklda beradi.</p><ul><li>Uslubiy ko&#39;rsatma ta&#39;rifi: UI Kit — dizaynerlar uchun vizual <strong>«konstruktor»</strong>: interfeysni noldan chizmasdan, tayyor bo&#39;laklardan yig&#39;ish.</li><li>UI Kit&#39;lar odatda Figma, Sketch, Adobe XD kabi dasturlar uchun tayyorlanadi va loyihaning dastlabki bosqichlarida qo&#39;llaniladi.</li><li>Asosiy maqsad — <strong>vaqtni tejash</strong> va brendning vizual tilini (rang palitrasi, tipografiya) saqlash.</li></ul><h3 id="_2-3-ui-kit-ning-4-afzalligi-qo-llanma" tabindex="-1">2.3. UI Kit&#39;ning 4 afzalligi (qo&#39;llanma) <a class="header-anchor" href="#_2-3-ui-kit-ning-4-afzalligi-qo-llanma" aria-label="Permalink to &quot;2.3. UI Kit&#39;ning 4 afzalligi (qo&#39;llanma)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Afzallik</th><th>Ma&#39;nosi</th><th>Misol</th></tr></thead><tbody><tr><td><strong>Vaqtni tejash</strong></td><td>elementni noldan yaratish shart emas</td><td>tayyor «Kirish» tugmasini nusxalash</td></tr><tr><td><strong>Vizual uyg&#39;unlik</strong></td><td>barcha komponentlar bir-biriga mos</td><td>hamma ekranda bir xil ko&#39;k va bir xil burchak</td></tr><tr><td><strong>Moslashuvchanlik</strong></td><td>kitni o&#39;z ehtiyojiga moslash mumkin</td><td>brend rangini almashtirish</td></tr><tr><td><strong>Jamoaviy ishlash</strong></td><td>dizayner va dasturchi uchun yagona vizual til</td><td>«Primary Button» — ikkalasi uchun bir xil narsa</td></tr></tbody></table><h3 id="_2-4-dizayn-tizimi-design-system" tabindex="-1">2.4. Dizayn tizimi (Design System) <a class="header-anchor" href="#_2-4-dizayn-tizimi-design-system" aria-label="Permalink to &quot;2.4. Dizayn tizimi (Design System)&quot;">​</a></h3><p><strong>Dizayn tizimi</strong> — faqat vizual elementlar to&#39;plami emas, balki mahsulot dizaynini yaratish va rivojlantirishga xizmat qiluvchi <strong>yagona konseptual tizim</strong>: kompaniyaning barcha interfeyslari bir xil mantiq, uslub va qoidalarga asoslanadi.</p><p>Uslubiy ko&#39;rsatma bo&#39;yicha <strong>5 asosiy qism</strong>:</p><ol><li><strong>Komponentlar (UI Elements)</strong> — tugma, input, karta, menyu.</li><li><strong>Vizual uslublar (Visual Styles / Tokens)</strong> — ranglar, tipografiya, bo&#39;shliqlar.</li><li><strong>Shablonlar (Templates / Layouts)</strong> — tayyor sahifa tuzilmalari.</li><li><strong>Prinsip va qo&#39;llanmalar (Principles &amp; Guidelines)</strong> — «qachon, qanday ishlatiladi» qoidalari.</li><li><strong>Hujjatlashtirish (Documentation)</strong> — hamma uchun yozma tavsif.</li></ol><h3 id="_2-5-ui-kit-va-dizayn-tizimi-farqi" tabindex="-1">2.5. UI Kit va dizayn tizimi farqi <a class="header-anchor" href="#_2-5-ui-kit-va-dizayn-tizimi-farqi" aria-label="Permalink to &quot;2.5. UI Kit va dizayn tizimi farqi&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>UI Kit</th><th>Dizayn tizimi</th></tr></thead><tbody><tr><td>Nima</td><td>tayyor komponentlar to&#39;plami</td><td>komponentlar + tokenlar + qoidalar + hujjatlar</td></tr><tr><td>Savol</td><td>«Nima bor?»</td><td>«Nima bor, qachon va nega ishlatiladi?»</td></tr><tr><td>O&#39;xshatish</td><td>LEGO bo&#39;laklari qutisi</td><td>LEGO qutisi + yig&#39;ish yo&#39;riqnomasi + qoidalar</td></tr><tr><td>Kim uchun</td><td>asosan dizayner</td><td>dizayner, dasturchi, menejer — butun jamoa</td></tr></tbody></table><p>UI Kit — dizayn tizimining <strong>bir qismi</strong>.</p><h3 id="_2-6-dizayn-tokenlari" tabindex="-1">2.6. Dizayn tokenlari <a class="header-anchor" href="#_2-6-dizayn-tokenlari" aria-label="Permalink to &quot;2.6. Dizayn tokenlari&quot;">​</a></h3><p><strong>Token</strong> — dizayn qarorining nomlangan qiymati:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>color-primary   = #2563EB     (asosiy rang)</span></span>
<span class="line"><span>color-text      = #1F2937</span></span>
<span class="line"><span>font-heading    = Poppins, 24px, SemiBold</span></span>
<span class="line"><span>font-body       = Inter, 16px, Regular</span></span>
<span class="line"><span>space-s = 8px   space-m = 16px   space-l = 24px   (8-point grid)</span></span>
<span class="line"><span>radius-m = 8px</span></span></code></pre></div><p>Token o&#39;zgarsa (masalan, brend rangi), u ishlatilgan barcha joy avtomatik yangilanadi — Figma&#39;da bu <strong>Styles</strong> (Color styles, Text styles) va <strong>Variables</strong> orqali amalga oshadi.</p><h3 id="_2-7-kichikdan-kattaga-atom-→-molekula-→-organizm" tabindex="-1">2.7. Kichikdan kattaga: atom → molekula → organizm <a class="header-anchor" href="#_2-7-kichikdan-kattaga-atom-→-molekula-→-organizm" aria-label="Permalink to &quot;2.7. Kichikdan kattaga: atom → molekula → organizm&quot;">​</a></h3><ul><li><strong>Atom</strong> — eng kichik bo&#39;lak: rang, shrift, ikonka, bitta tugma.</li><li><strong>Molekula</strong> — bir nechta atom: qidiruv maydoni (input + tugma + ikonka).</li><li><strong>Organizm</strong> — molekulalar majmuasi: header (logo + qidiruv + profil + savat). Shablon va sahifa shu bo&#39;laklardan yig&#39;iladi. (Bu yondashuv amalda Atomic Design deb ataladi.)</li></ul><hr>`,21))]),i("div",k,[i("h2",p,[r(n,{name:"file-text"}),a[6]||(a[6]=t(" 3. Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> 3. Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=l('<h3 id="_1-topshiriq-ui-kit-yoki-dizayn-tizimi-oson" tabindex="-1">1-topshiriq. UI Kit yoki dizayn tizimi? (oson) <a class="header-anchor" href="#_1-topshiriq-ui-kit-yoki-dizayn-tizimi-oson" aria-label="Permalink to &quot;1-topshiriq. UI Kit yoki dizayn tizimi? (oson)&quot;">​</a></h3><p>Quyidagilarni ajrating: (a) 20 ta tayyor tugma va ikonka fayli; (b) tugmalar + ranglar + «asosiy tugma sahifada bitta bo&#39;ladi» qoidasi + hujjat sayti; (c) Figma&#39;dagi «Mobile UI Kit» shabloni.</p><p><strong>Yechim:</strong> (a) UI Kit; (b) dizayn tizimi — komponent, token, prinsip va hujjat bor; (c) UI Kit.</p><h3 id="_2-topshiriq-tokenlar-jadvali-o-rta" tabindex="-1">2-topshiriq. Tokenlar jadvali (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-tokenlar-jadvali-o-rta" aria-label="Permalink to &quot;2-topshiriq. Tokenlar jadvali (o&#39;rta)&quot;">​</a></h3><p>4-haftadagi «E-kutubxona» uchun token jadvalini tuzing: 5 ta rang (primary, secondary, fon, matn, xato), 3 ta matn uslubi (H1, H2, Body), 4 ta bo&#39;shliq (8, 16, 24, 32).</p><p><strong>Yechim (namuna):</strong></p><table tabindex="0"><thead><tr><th>Token</th><th>Qiymat</th></tr></thead><tbody><tr><td>color-primary</td><td>#2563EB</td></tr><tr><td>color-secondary</td><td>#F59E0B</td></tr><tr><td>color-bg</td><td>#F9FAFB</td></tr><tr><td>color-text</td><td>#111827</td></tr><tr><td>color-error</td><td>#DC2626</td></tr><tr><td>text-h1</td><td>Poppins 28 / SemiBold</td></tr><tr><td>text-h2</td><td>Poppins 20 / SemiBold</td></tr><tr><td>text-body</td><td>Inter 16 / Regular, line-height 150%</td></tr><tr><td>space</td><td>8 · 16 · 24 · 32</td></tr></tbody></table><p>Tekshirish: primary rang oq matn bilan WCAG 4.5:1 kontrastga javob beradimi (11-dars).</p><h3 id="_3-topshiriq-figma-da-mini-ui-kit-sahifasi-qiyin" tabindex="-1">3-topshiriq. Figma&#39;da mini UI kit sahifasi (qiyin) <a class="header-anchor" href="#_3-topshiriq-figma-da-mini-ui-kit-sahifasi-qiyin" aria-label="Permalink to &quot;3-topshiriq. Figma&#39;da mini UI kit sahifasi (qiyin)&quot;">​</a></h3><p>Figma&#39;da <code>UI Kit</code> nomli yangi sahifa (Page) oching va 3 ta bo&#39;lim yarating:</p><ol><li><strong>Colors</strong> — 5 ta 80 × 80 kvadrat; har biri <strong>Color style</strong> sifatida saqlangan (Fill → Style belgisi → <strong>+</strong> → nom: <code>Primary/500</code>).</li><li><strong>Typography</strong> — H1, H2, Body, Caption namunalari; har biri <strong>Text style</strong>.</li><li><strong>Buttons</strong> — Primary, Secondary, Disabled tugmalari: 160 × 48, corner radius 8, matn Body style, faqat yaratilgan stillardan foydalanilgan.</li></ol><p><strong>Yechim (tekshiruv):</strong> o&#39;ng paneldagi «Local styles» ro&#39;yxatida 5 ta rang va 4 ta matn uslubi bor; tugmalarda HEX qiymat qo&#39;lda yozilmagan, balki stil nomi ko&#39;rinadi; Primary rangni o&#39;zgartirganda Primary tugma ham avtomatik o&#39;zgaradi.</p><hr>',13))]),i("div",b,[i("h2",z,[r(n,{name:"file-text"}),a[9]||(a[9]=t(" 4. Tezkor nazorat (savollar va javoblar) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-nazorat-savollar-va-javoblar","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor nazorat (savollar va javoblar)"'},"​",-1))]),a[11]||(a[11]=l("<ol><li><strong>UI Kit nima?</strong><ul><li><em>Javob:</em> Dizaynerlar va dasturchilar uchun tayyor, qayta ishlatiladigan interfeys komponentlari to&#39;plami.</li></ul></li><li><strong>UI Kit&#39;ning 4 afzalligi?</strong><ul><li><em>Javob:</em> Vaqtni tejash, vizual uyg&#39;unlik, moslashuvchanlik, jamoaviy ishlash.</li></ul></li><li><strong>Dizayn tizimining 5 qismi?</strong><ul><li><em>Javob:</em> Komponentlar, vizual uslublar (tokenlar), shablonlar, prinsip va qo&#39;llanmalar, hujjatlashtirish.</li></ul></li><li><strong>UI Kit va dizayn tizimi farqi?</strong><ul><li><em>Javob:</em> UI Kit — komponentlar to&#39;plami; dizayn tizimi — komponentlar + tokenlar + qoidalar + hujjatlar; UI Kit uning bir qismi.</li></ul></li><li><strong>Dizayn tokeni nima?</strong><ul><li><em>Javob:</em> Dizayn qarorining nomlangan qiymati (masalan, <code>color-primary = #2563EB</code>), o&#39;zgarsa hamma joyda yangilanadi.</li></ul></li></ol><hr>",2))]),i("div",f,[i("h2",v,[r(n,{name:"file-text"}),a[12]||(a[12]=t(" 5. Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-uyga-vazifa","aria-label":'Permalink to "<Icon name="file-text" /> 5. Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("ol",null,[i("li",null,[t("«E-kutubxona» UI kit sahifasini davom ettiring: Colors, Typography, Buttons bo'limlariga "),i("strong",null,"Inputs"),t(" (oddiy, fokus, xato holatlari) bo'limini qo'shing.")]),i("li",null,"Barcha elementlarda faqat Color va Text styles'dan foydalaning."),i("li",null,"Token jadvalini (rang, shrift, bo'shliq) Figma sahifasining yon tomoniga matn sifatida yozing.")],-1))])])}const K=o(m,[["render",q]]);export{j as __pageData,K as default};
